insert into public.companies (id, slug, name, category, tagline, about, website, registry_id, registry_verified, city, founded, price_range, claimed, status) values ('00000000-0000-4000-8000-000000000011', 'green-candle', 'קורס הנר הירוק', 'courses', 'קורס מסחר במניות אמריקאיות למתחילים', 'קורס דיגיטלי של 40 שיעורים מוקלטים ומפגש זום שבועי. מתמקד בניתוח טכני ובניהול סיכונים למסחר יומי.', 'https://green-candle.example', '51-555001-2', true, 'תל אביב', 2019, '₪2,900–₪4,500', true, 'published');
insert into public.companies (id, slug, name, category, tagline, about, website, registry_id, registry_verified, city, founded, price_range, claimed, status) values ('00000000-0000-4000-8000-000000000012', 'eye-level-trading', 'מסחר בגובה העיניים', 'mentoring', 'ליווי אישי צמוד לשלושה חודשים', 'תוכנית ליווי אחד-על-אחד: פגישה שבועית, בניית תוכנית מסחר אישית ומעבר על יומן העסקאות.', 'https://eye-level.example', '51-555002-0', true, 'חיפה', 2021, '₪6,000–₪9,000', false, 'published');
insert into public.companies (id, slug, name, category, tagline, about, website, registry_id, registry_verified, city, founded, price_range, claimed, status) values ('00000000-0000-4000-8000-000000000013', 'signal-bot-pro', 'סיגנל-בוט פרו', 'signals', 'קבוצת איתותי קריפטו בטלגרם', 'מנוי חודשי לקבוצת טלגרם שמפרסמת איתותי קנייה ומכירה למטבעות קריפטו.', 'https://signalbot.example', 'ע.מ. 0-555003-1', false, null, 2023, '₪390 לחודש', false, 'published');
insert into public.companies (id, slug, name, category, tagline, about, website, registry_id, registry_verified, city, founded, price_range, claimed, status) values ('00000000-0000-4000-8000-000000000014', 'nachshon-trading-house', 'בית המסחר נחשון', 'courses', 'קורס פרונטלי למסחר בשוק ההון', 'קורס של 12 מפגשים פרונטליים בכיתה, כולל סימולטור מסחר וגישה לקהילת בוגרים.', 'https://nachshon.example', '51-555004-6', true, 'ירושלים', 2016, '₪5,200', true, 'published');
insert into public.companies (id, slug, name, category, tagline, about, website, registry_id, registry_verified, city, founded, price_range, claimed, status) values ('00000000-0000-4000-8000-000000000015', 'gal-trade-algo', 'גל-טרייד אלגו', 'algo', 'בוט מסחר אוטומטי במנוי', 'תוכנה שמתחברת לחשבון הברוקר ומבצעת עסקאות לפי אסטרטגיות מוכנות. מנוי חודשי.', 'https://galtrade.example', '51-555005-3', true, 'רמת גן', 2022, '₪250–₪600 לחודש', false, 'published');
insert into public.companies (id, slug, name, category, tagline, about, website, registry_id, registry_verified, city, founded, price_range, claimed, status) values ('00000000-0000-4000-8000-000000000016', 'wolf-street-mentoring', 'מנטורינג וולף-סטריט', 'mentoring', 'תוכנית ״מסחר כמקצוע״', 'תוכנית ליווי קבוצתית של חצי שנה עם הבטחה ל״מקצוע חדש״. כוללת מפגשי קבוצה ותכנים מוקלטים.', 'https://wolfstreet.example', '51-555006-1', true, 'הרצליה', 2020, '₪14,900', false, 'published');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000211', '00000000-0000-4000-8000-000000000011', '8fdb887b-3cfe-49e3-80fb-0e1c2e9018f2', 'מיכל ש.', 5, 'סוף סוף מישהו שמדבר על ניהול סיכונים', 'לקחתי קורס אחר לפני זה שכולו היה צילומי מסך של רווחים. כאן חצי מהחומר הוא על איך לא להפסיד, וזה מה שהייתי צריכה. המפגשים השבועיים באמת קורים, והמרצה עונה לשאלות.', true, 3400, true, 'published', '2026-09-21T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000212', '00000000-0000-4000-8000-000000000011', 'b1b523ce-0a2e-4ef2-8571-3f001f05bd99', 'יוסי ב.', 4, 'תוכן טוב, תמיכה איטית', 'החומר מסודר וברור. הורדתי כוכב כי לקח שבוע לקבל תשובה במייל על בעיה בגישה לשיעורים.', true, 2900, true, 'published', '2026-08-30T10:00:00.000Z');
insert into public.review_replies (review_id, company_id, body, created_at) values ('00000000-0000-4000-8000-000000000212', '00000000-0000-4000-8000-000000000011', 'תודה יוסי. הוספנו מאז נציג תמיכה בוואטסאפ וזמן התגובה הממוצע ירד לפחות מיום. נשמח אם תנסה שוב.', '2026-09-02T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000213', '00000000-0000-4000-8000-000000000011', 'c25b0a91-e4cf-495b-870d-b1212d7710d3', 'אורי ג.', 2, 'לא מתאים למי שעובד במשרה מלאה', 'המסחר היומי שהם מלמדים דורש להיות מול המסך בשעות המסחר בארה״ב. זה לא נאמר בשיחת המכירה, וגיליתי את זה אחרי שכבר שילמתי.', false, null, false, 'published', '2026-07-14T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000221', '00000000-0000-4000-8000-000000000012', '803689ff-f5cb-4351-846e-426d568fbb0c', 'נועה ר.', 5, 'המנטור באמת מסתכל על העסקאות שלך', 'כל שבוע עברנו על יומן המסחר שלי. זה היה מביך בהתחלה ושימושי מאוד בהמשך. יקר, אבל קיבלתי מה שהובטח.', true, 7500, true, 'published', '2026-09-10T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000222', '00000000-0000-4000-8000-000000000012', '75aee5db-d6fb-4460-81c2-2b07cdc541de', 'רון ח.', 4, 'טוב, אבל המחיר גבוה', 'הליווי מקצועי והמנטור זמין. הייתי שמח לאפשרות של חודש ניסיון במקום התחייבות מראש לשלושה חודשים.', true, 6000, true, 'published', '2026-06-03T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000231', '00000000-0000-4000-8000-000000000013', '968133a8-b19a-4894-8c36-8e3361be0874', 'דניאל מ.', 1, 'ביטול המנוי היה בלתי אפשרי', 'ניסיתי לבטל שלוש פעמים דרך הטלגרם ולא קיבלתי תשובה. בסוף ביטלתי דרך חברת האשראי. האיתותים עצמם הגיעו לרוב אחרי שהמחיר כבר זז.', true, 1170, true, 'published', '2026-09-28T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000232', '00000000-0000-4000-8000-000000000013', '84266878-e216-4240-8741-14f907275c33', 'שירן ק.', 1, 'צילומי מסך של רווחים, בלי היסטוריה מלאה', 'ביקשתי לראות את כל ההיסטוריה של האיתותים, כולל ההפסדים. סירבו ואמרו שזה ״סוד מקצועי״.', false, null, false, 'published', '2026-08-19T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000233', '00000000-0000-4000-8000-000000000013', '0e5dc573-d231-4b74-887d-9c77b5df2f5c', 'עמית ל.', 5, 'הרווחתי בחודש הראשון', 'היה חודש טוב, נכנסתי לפי האיתותים ויצאתי ברווח. לא בדקתי איך הם הצליחו בחודשים שלפני שהצטרפתי.', false, null, false, 'published', '2026-08-02T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000241', '00000000-0000-4000-8000-000000000014', '17d58aa7-6c07-4620-811a-678b758838c2', 'אביטל נ.', 3, 'מפגשים טובים, חומר קצת מיושן', 'המרצים נחמדים והמפגשים בכיתה עוזרים לשאול שאלות. חלק מהדוגמאות מ-2018 ומרגישות לא רלוונטיות.', true, 5200, true, 'published', '2026-09-05T10:00:00.000Z');
insert into public.review_replies (review_id, company_id, body, created_at) values ('00000000-0000-4000-8000-000000000241', '00000000-0000-4000-8000-000000000014', 'תודה על ההערה. אנחנו מעדכנים את סילבוס המחזור הבא ומחליפים את כל הדוגמאות לדוגמאות מהשנתיים האחרונות.', '2026-09-07T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000242', '00000000-0000-4000-8000-000000000014', '60d98069-7e5c-480a-807e-d71eb05fdbf9', 'גיל פ.', 4, 'הסימולטור שווה את זה', 'תרגלתי בסימולטור חודשיים לפני שהכנסתי כסף אמיתי. ההמלצה הזו לבדה חסכה לי הרבה כסף.', true, 5200, true, 'published', '2026-07-22T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000251', '00000000-0000-4000-8000-000000000015', '98dc6919-3927-497c-847f-14f332f6d5b8', 'טל ו.', 2, 'התוצאות בבקטסט לא דומות למציאות', 'הבקטסטים באתר מרשימים. בחשבון אמיתי, אחרי עמלות, יצאתי בהפסד קטן אחרי ארבעה חודשים. התוכנה עצמה יציבה.', true, 1600, true, 'published', '2026-09-14T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000252', '00000000-0000-4000-8000-000000000015', 'bc64aa41-3cd9-426a-802e-0e0309b0b387', 'ליאור ד.', 4, 'כלי טוב למי שמבין מה הוא עושה', 'אני משתמש בו לאוטומציה של האסטרטגיה שלי, לא באסטרטגיות המוכנות. בתור כלי הוא עושה את העבודה.', true, 3000, true, 'published', '2026-08-11T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000261', '00000000-0000-4000-8000-000000000016', 'ad28a235-a182-4b5c-88ec-5db0c29ba920', 'אלון צ.', 1, 'לחץ מכירה אגרסיבי', 'בשיחת המכירה אמרו לי שהמקומות נגמרים היום ושאפשר לפרוס ל-36 תשלומים. אחרי ההרשמה רוב התוכן היה מוקלט, לא הליווי שהובטח.', true, 14900, true, 'published', '2026-09-25T10:00:00.000Z');
insert into public.reviews (id, company_id, user_id, author_name, rating, title, body, paid, amount_paid, verified_purchase, status, created_at) values ('00000000-0000-4000-8000-000000000262', '00000000-0000-4000-8000-000000000016', 'f4cab2bc-360c-44aa-83e2-2bd228e07117', 'הדס א.', 5, 'שינה לי את החשיבה', 'המפגשים הקבוצתיים נתנו לי הרבה מוטיבציה וחברים לדרך. עדיין לא מרוויחה, אבל מבינה הרבה יותר.', true, 14900, true, 'published', '2026-08-08T10:00:00.000Z');
